int restore_fpu_checking(struct task_struct *tsk) {
    if (cpu_has_fpu_feature) {
        /* Clear x87 state with defined values */
        __asm__ __volatile__(
            "fninit\n"
            "fldz\n"
            "fld1\n"
            "fldpi\n"
            "fldl2e\n"
            "fldl2t\n"
            "fstcw %0"
            : "=m"(*tsk->fpu.state));
    }

    return do_fpu_restore_check(tsk);
